"""Methods generated by the inventory (Implementation Decision 17; ticket 108).

The paper's Methods states what actually ran. At every render of `research/sections/methods.md` the methods inventory
generates, after the section's passages and under `sections.INVENTORY`, three parts no model writes:

- **the parameter table** (`parameter_rows`): method, parameter, value, default, reason, and a `code` tag resolved
  against `main`, one row per entry of the current results' `parameters` (ticket 107), which the conductor keeps
  beside each integrated attempt's session (`methods.json`). A later ticket's entry for the same method, parameter,
  and file replaces an earlier one; a row whose file `main` no longer holds is not current and leaves the table. A
  reason is editable like a passage: the owner says it (`wayline passage add --section methods --parameter
  <method>:<name>[@<path>]`) or edits the Reason cell of its row in the file, which is taken in before the next render
  as the owner's passage for that row (`parameter` on the passage, `taken_reasons`), and later renders show it.
- **the software** and its exact versions (`software`), from the locks ticket 106 renders under `code/locks/` (the
  project's `code/` locks themselves before any is rendered), and the tools the cited jobs called.
- **a proposed citation** (`citations`) only for a package whose method a current Methods passage relies on (it names
  the method by an alias of the alias table, `methods/aliases.json`) and that publishes a preferred citation: a
  `CITATION.cff` in the package as the project's environment installed it, or its documented equivalent, recorded in
  `methods/citations.json` with where the package publishes it. Other packages get none.

**The rule from Methods to code** is no gate (`no_code`): a current Methods passage naming a method with no code behind
it (a `code` tag `main` does not hold, or a method of the alias table no file under `code/` on `main` calls) is listed
among the outline's gaps and never failed, and the data and code availability statement's inputs
(`research/methods_inventory.json`, `not_reproduced`) mark it as not reproduced by the code repository.

Each render writes `research/methods_inventory.json` (schema `methods_inventory`) when what it generated changed.
"""

import hashlib
import json
import re
import subprocess
from pathlib import Path

from wayline import methods, reproduce, sections
from wayline import software as software_module
from wayline.ledger import ledger_for

__all__ = [
    "INVENTORY_JSON", "SCHEMA", "PARAMETERS", "parameter_rows", "row_key", "block", "taken_reasons", "parameter_key",
    "parse_parameter", "software", "relied_on", "citations", "no_code", "gap_lines", "read_record", "availability",
]

INVENTORY_JSON = "methods_inventory.json"
SCHEMA = "methods_inventory"
PARAMETERS = "Parameters"  # the heading of the table, and of an owner's reason passage
SESSIONS = "sessions"
HEADER = "| Method | Parameter | Value | Default | Reason | Code |"
NOT_SEEN = "not seen by the parsers"
# `<method>:<name>[@<path>]`: a method may hold `:` itself (R's `stats::optim`), a parameter's name never does.
_PARAMETER = re.compile(r"^([^@\s][^@]*):([^:@\s][^:@]*?)(?:@(\S+))?$")


def _one_line(text):
    return " ".join(str(text or "").split())


def _digest(text):
    return hashlib.sha256(_one_line(text).encode("utf-8")).hexdigest()[:16]


# --- the parameter table --------------------------------------------------------------------------------------


def parameter_key(method, name, path=None):
    """What an owner's reason passage names (`parameter`): `<method>:<name>`, `@<path>` for one file only."""
    return "%s:%s%s" % (_one_line(method), _one_line(name), "@%s" % path if path else "")


def parse_parameter(key):
    """`(method, name, path or None)` of a `parameter` key, or None when it is not one."""
    found = _PARAMETER.match(_one_line(key))
    return (found.group(1).strip(), found.group(2).strip(), found.group(3)) if found else None


def row_key(row):
    """One printed row's key: its method, parameter, and where its `code` tag points."""
    where = "@%s#L%s" % (row["path"], row["line"]) if row.get("path") and row.get("line") else ("@%s" % row["path"] if row.get("path") else "")
    return "%s:%s%s" % (_one_line(row.get("method")), _one_line(row.get("name")), where)


def _integrated(book):
    """`[(ticket, when, entries)]`: each ticket's last attempt with a `methods.json`, in the order the tickets reached
    `main` (their last `integrated` event; one with none, before them all, by id), `when` that event's time or ""."""
    from wayline.ledger import INTEGRATED

    latest = {}
    root = book.research / SESSIONS
    for path in root.glob("*/*/%s" % methods.CODE_RULE_FILE):
        ticket, attempt = path.parent.parent.name, path.parent.name
        if not (ticket.isdigit() and attempt.isdigit()):
            continue
        if int(attempt) > latest.get(int(ticket), (0, None))[0]:
            latest[int(ticket)] = (int(attempt), path.parent)
    reached = {}
    if latest:
        events, _ = book.read_events()
        for position, event in enumerate(events):
            if event.get("event") == INTEGRATED and (event.get("payload") or {}).get("ticket") in latest:
                reached[event["payload"]["ticket"]] = (position, str(event.get("ts") or ""))
    found = []
    for ticket in sorted(latest, key=lambda number: (reached.get(number, (-1, ""))[0], number)):
        rule = methods.read_code_rule(latest[ticket][1]) or {}
        found.append((ticket, reached.get(ticket, (-1, ""))[1], [entry for entry in rule.get("parameters") or [] if isinstance(entry, dict)]))
    return found


def _owner_reasons(book):
    """`[(method, name, path or None, reason, when)]`: the owner's reason passages, oldest first."""
    found = []
    for item in sections.read_passages(book):
        if item.get("section") != "methods" or not item.get("parameter") or item.get("withdrawn"):
            continue
        parsed = parse_parameter(item["parameter"])
        if parsed is not None:
            found.append(parsed + (_one_line(item.get("text")), str(item.get("ts") or "")))
    return found


def _remembered(read):
    """`read` reading each file once: a render resolves many tags against the same few files."""
    if getattr(read, "remembered", False):
        return read
    seen = {}

    def remembered(path):
        if path not in seen:
            seen[path] = read(path)
        return seen[path]

    remembered.where = getattr(read, "where", "")
    remembered.remembered = True
    return remembered


def main_read(project):
    """What one render resolves `code` tags against, each file of `main` read once."""
    from wayline import provenance  # the provenance module pulls in the gates and the report
    return _remembered(provenance.main_reader(project))


def _key(entry):
    return (entry.get("path"), _one_line(entry.get("method")), _one_line(entry.get("name")))


def parameter_rows(project_or_ledger, read=None):
    """The table's rows: `[{method, name, value, default, reason, path, line, ticket, by, code}]`, in the order the tickets
    reached `main`.

    `read` is what `code` tags resolve against (`main_read` by default): a row whose file or line it does not hold is no
    longer current. A later ticket's entries for a method, parameter, and file replace an earlier one's. The owner's
    latest reason for a row stands in place of the ticket's while the row's value is the one the owner gave it for: a
    later ticket that changes the value brings its own reason back.
    """
    from wayline import provenance  # the provenance module pulls in the gates and the report

    book = ledger_for(project_or_ledger)
    read = _remembered(read or provenance.main_reader(book.project))
    rows, order, since = {}, [], {}
    for ticket, when, entries in _integrated(book):
        given = {}
        for entry in entries:
            given.setdefault(_key(entry), []).append(entry)
        for key, held in given.items():
            values = sorted(str(entry.get("value")) for entry in held)
            if key not in rows or sorted(str(row.get("value")) for row in rows[key]) != values:
                since[key] = when  # the value as it stands now, since this ticket set it
            rows[key] = [dict(entry, ticket=ticket, by="t%d" % ticket) for entry in held]
            if key not in order:
                order.append(key)
    owners = _owner_reasons(book)
    found = []
    for key in order:
        for row in rows.get(key, []):
            path = row.get("path")
            if path:
                line = int(row["line"]) if str(row.get("line") or "").isdigit() and int(row["line"]) > 0 else 1
                if provenance.code_tag_problem(read, {"path": path, "locator": "L%d" % line}) is not None:
                    continue  # its file or its line is no longer on `main`: not current
                row["line"] = line
                row["code"] = "{code:%s#L%d}" % (path, line)
            else:
                row["code"] = None
            for method, name, where, reason, when in owners:
                if method == _one_line(row.get("method")) and name == _one_line(row.get("name")) and where in (None, path) \
                        and when >= since.get(key, ""):
                    row["reason"], row["by"] = reason, "owner"
            found.append(row)
    return found


def _cell(text):
    return _one_line(text).replace("|", "\\|") or " "


def _value(row, field):
    value = row.get(field)
    if value is not None:
        return str(value)
    if field == "default" and row.get("path"):
        return "its own"  # a developed method's own default: there is no library default behind it
    return "not given"


def _table(rows):
    lines = ["## %s" % PARAMETERS, "",
             "Code generates this table from the tickets' `parameters` at every render. Edit a reason in its row, or say "
             "it, and it is taken in as yours.", "", HEADER, "| --- | --- | --- | --- | --- | --- |"]
    for row in rows:
        lines.append("| `%s` | `%s` | %s | %s | %s | %s |" % (
            _cell(row.get("method")), _cell(row.get("name")), _cell(_value(row, "value")), _cell(_value(row, "default")),
            _cell(row.get("reason")), row["code"] or NOT_SEEN))
    return lines + [""]


# --- the software and its versions -----------------------------------------------------------------------------


# The package locks ticket 82 writes under `code/` (`software.LOCKS`), each read under the name Methods gives its language.
LANGUAGES = tuple((software_module.LOCKS[language], label) for language, label in (
    (software_module.PYTHON, "Python"), (software_module.R, "R"), (software_module.JULIA, "Julia"),
    (software_module.OCTAVE, "Octave Forge")))
# Where ticket 106 renders the locks as each cited run's commit held them, and the cited jobs' tools.
LOCKS_DIR, TOOLS_LOCK = reproduce.LOCKS_DIR, reproduce.TOOLS_LOCK
_REQUIREMENT = re.compile(r"^([A-Za-z0-9][A-Za-z0-9._-]*)(?:\[[^\]]*\])?\s*===?\s*([^\s;#]+)")
_JULIA_DEP = re.compile(r"^\[\[(?:deps\.)?([A-Za-z0-9_]+)\]\]\s*$")
_JULIA_VERSION = re.compile(r'^version\s*=\s*"([^"]+)"')
_OCTAVE_ROW = re.compile(r"^\s*(\S+?)\s*\*?\s*\|\s*([0-9]\S*)\s*\|", re.M)


def _packages(name, text):
    """`[(package, version)]` one lock file pins."""
    if name == "requirements.lock":
        return [found.groups() for found in (_REQUIREMENT.match(line.strip()) for line in text.splitlines()) if found]
    if name == "renv.lock":
        try:
            held = json.loads(text).get("Packages") or {}
        except (ValueError, AttributeError):
            return []
        return [(str(entry.get("Package") or package), str(entry["Version"])) for package, entry in held.items()
                if isinstance(entry, dict) and entry.get("Version")]
    if name == "Manifest.toml":
        found, current = [], None
        for line in text.splitlines():
            dep = _JULIA_DEP.match(line.strip())
            if dep:
                current = dep.group(1)
                continue
            version = _JULIA_VERSION.match(line.strip())
            if version and current:
                found.append((current, version.group(1)))
                current = None
        return found
    return _OCTAVE_ROW.findall(text)


def _version_key(version):
    return [(0, int(part), "") if part.isdigit() else (1, 0, part) for part in re.split(r"[.\-+]", str(version))]


def software(project):
    """The software Methods lists: `[{language, packages: [{name, versions}], locks}]` from the locks ticket 106 renders
    under `code/locks/<commit>/` (the project's own `code/` locks while none is rendered), then the tools the cited jobs
    called (`code/locks/tools.json`), each with every exact version a lock pins."""
    code = Path(project) / methods.CODE
    rendered = code / LOCKS_DIR
    found = []
    for name, language in LANGUAGES:
        files = sorted(path for path in rendered.glob("*/%s" % name) if path.is_file()) if rendered.is_dir() else []
        if not files and (code / name).is_file():
            files = [code / name]
        versions = {}
        for path in files:
            try:
                text = path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            for package, version in _packages(name, text):
                versions.setdefault(package, set()).add(version)
        if versions:
            found.append({"language": language,
                          "packages": [{"name": package, "versions": sorted(versions[package], key=_version_key)}
                                       for package in sorted(versions, key=str.casefold)],
                          "locks": [path.relative_to(Path(project)).as_posix() for path in files]})
    try:
        tools = json.loads((rendered / TOOLS_LOCK).read_text(encoding="utf-8")).get("tools") or []
    except (OSError, ValueError, AttributeError):
        tools = []
    versions = {}
    for tool in tools:
        if isinstance(tool, dict) and tool.get("name") and tool.get("version"):
            versions.setdefault(str(tool["name"]), set()).add(str(tool["version"]))
    if versions:
        found.append({"language": "Tools", "packages": [{"name": name, "versions": sorted(versions[name], key=_version_key)}
                                                        for name in sorted(versions, key=str.casefold)],
                      "locks": ["%s/%s/%s" % (methods.CODE, LOCKS_DIR, TOOLS_LOCK)]})
    return found


def _software_lines(listed):
    lines = ["## Software", "", "The exact versions the environment locks in `code/` pin, as the cited runs ran them.", ""]
    for entry in listed:
        lines.append("- %s: %s" % (entry["language"], ", ".join(
            "%s %s" % (package["name"], " and ".join(package["versions"])) for package in entry["packages"])))
    return lines + [""]


# --- the proposed citations --------------------------------------------------------------------------------------


CITATIONS = "citations"  # methods/citations.json: the preferred citations packages publish beside their code
CFF = "CITATION.cff"


def _citation_table():
    try:
        return json.loads((methods.TABLES / ("%s.json" % CITATIONS)).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def _normal(name):
    return re.sub(r"[-_.]+", "-", str(name or "")).lower()


def _methods_passages(book):
    """The current Methods passages (the owner's reasons for parameters are the table's)."""
    return sections.arranged(book, "methods", ordered=False).current()


def relied_on(project_or_ledger, passages=None):
    """`{distribution: [(method, [passage ids])]}`: each package a current Methods passage relies on, by naming one of its
    methods by an alias of the alias table."""
    book = ledger_for(project_or_ledger)
    passages = _methods_passages(book) if passages is None else passages
    renamed = _citation_table().get("distributions") or {}
    found = {}
    for call, entry in methods.aliases()["python"].items():
        method = entry.get("method") or call
        named = [item["id"] for item in passages
                 if any(methods._names(alias, str(item.get("text") or "")) for alias in list(entry.get("aliases") or []) + [method] if alias)]
        if not named:
            continue
        root = call.split(".")[0]
        distribution = renamed.get(root, root)
        held = found.setdefault(distribution, [])
        if not any(seen == method for seen, _ in held):
            held.append((method, named))
    return found


def _cff_fields(text):
    """`(title, doi, first author, year)` of a CITATION.cff, from its `preferred-citation` when it has one."""
    lines = text.splitlines()
    start = next((index for index, line in enumerate(lines) if line.startswith("preferred-citation:")), None)
    if start is not None:
        block_lines = []
        for line in lines[start + 1:]:
            if line.strip() and not line.startswith((" ", "\t")):
                break
            block_lines.append(line)
        lines = block_lines

    def field(name):
        for line in lines:
            found = re.match(r'^\s*(?:-\s*)?%s:\s*"?([^"]*?)"?\s*$' % re.escape(name), line)
            if found and found.group(1).strip():
                value = found.group(1).strip()
                return None if value[:1] in (">", "|") else value  # a folded scalar this reader does not unfold
        return None

    return field("title"), field("doi"), field("family-names"), field("year")


# Where a project's Python environment keeps its packages: the shared tools' project venv, or the project's own conda
# prefix or venv (`environment.PLACES`). A container's image is not opened.
ENVIRONMENTS = (".venv", ".wayline/env", ".wayline/env-venv")


def _installed_cff(project, distribution, module):
    """`(text, path)` of the CITATION.cff the package carries as the project's environment installed it, or None: in the
    package's own directory, or its `.dist-info` (beside its license files)."""
    wanted = {_normal(distribution).replace("-", "_"), _normal(module).replace("-", "_")}
    for place in ENVIRONMENTS:
        for packages in sorted((Path(project) / place).glob("lib/python*/site-packages")):
            candidates = [packages / name / CFF for name in wanted]
            candidates += [info / where / CFF for info in sorted(packages.glob("*.dist-info"))
                           if info.name.split("-")[0].lower().replace(".", "_") in wanted for where in (".", "licenses")]
            for path in candidates:
                if path.is_file():
                    try:
                        return path.read_text(encoding="utf-8", errors="replace"), path.relative_to(Path(project)).as_posix()
                    except OSError:
                        continue
    return None


def citations(project_or_ledger, listed=None, passages=None):
    """The citations Methods proposes: `[{package, method, passages, citation, doi, source}]`, one per package a current
    Methods passage relies on that the locks pin and that publishes a preferred citation; every other package gets none."""
    book = ledger_for(project_or_ledger)
    listed = software(book.project) if listed is None else listed
    pinned = {_normal(package["name"]) for entry in listed if entry["language"] == "Python" for package in entry["packages"]}
    table = _citation_table()
    published = {_normal(name): entry for name, entry in (table.get("python") or {}).items()}
    modules = {distribution: module for module, distribution in (table.get("distributions") or {}).items()}
    found = []
    for distribution, uses in sorted(relied_on(book, passages).items()):
        if _normal(distribution) not in pinned:
            continue
        installed = _installed_cff(book.project, distribution, modules.get(distribution, distribution))
        title, doi, author, year = _cff_fields(installed[0]) if installed is not None else (None, None, None, None)
        if title:
            said = "%s%s%s." % ("%s et al. " % author if author else "", "(%s). " % year if year else "", title)
            entry = {"citation": said, "doi": doi, "source": "its %s (`%s`)" % (CFF, installed[1])}
        elif _normal(distribution) in published:
            entry = published[_normal(distribution)]
            entry = {"citation": entry.get("citation"), "doi": entry.get("doi"), "source": "its %s" % entry.get("source")}
        else:
            continue
        for method, ids in uses:
            found.append(dict(entry, package=distribution, method=method, passages=list(ids)))
    return found


def _citation_lines(found):
    lines = ["## Proposed citations", "",
             "Each package a Methods passage relies on that publishes the citation it prefers. Proposed, not cited: a "
             "reference enters the paper once it is scouted and a passage cites it.", ""]
    for entry in found:
        lines.append("- %s (%s, %s): %s%s, as %s asks." % (
            entry["package"], entry["method"], ", ".join(entry["passages"]), entry["citation"],
            " doi:%s" % entry["doi"] if entry.get("doi") else "", entry["source"]))
    return lines + [""]


# --- the rule from Methods to code -------------------------------------------------------------------------------


def _calls(project, names):
    """Which of `names` a file under `code/` on `main` writes as a whole word (the working tree without a `main`)."""
    names = sorted({name for name in names if re.match(r"^\w+$", name)})
    if not names:
        return set()
    has_main = subprocess.run(["git", "-C", str(project), "rev-parse", "--verify", "-q", "main^{commit}"],
                              capture_output=True).returncode == 0
    argv = ["git", "-C", str(project), "grep", "-I", "-w", "-o", "-h"]
    for name in names:
        argv += ["-e", name]
    argv += (["main"] if has_main else ["--untracked"]) + ["--", methods.CODE + "/"]
    done = subprocess.run(argv, capture_output=True)
    if done.returncode not in (0, 1):
        return set()
    found = set()
    for line in done.stdout.decode("utf-8", errors="replace").splitlines():
        found.add(line.rsplit(":", 1)[-1].strip())
    return found & set(names)


def no_code(project_or_ledger, passages=None, read=None):
    """Each current Methods passage naming a method with no code behind it: `[{passage, heading, named, why}]`.

    Each `code` tag of a passage that `main` does not hold is listed, whatever its other tags name. A passage
    with no `code` tag is listed for each method of the alias table it names (by an alias, as written) when no file under
    `code/` on `main` calls any routine the table gives that alias to. Listed, never failed: the rule from Methods to code
    is no gate.
    """
    from wayline import provenance  # the provenance module pulls in the gates and the report

    book = ledger_for(project_or_ledger)
    passages = _methods_passages(book) if passages is None else passages
    read = _remembered(read or provenance.main_reader(book.project))
    table = methods.aliases()
    calls_of = {}  # alias, folded -> (alias as the table writes it, method, {short call names})
    for language, entries in table.items():
        for call, entry in entries.items():
            for alias in list(entry.get("aliases") or []) + [entry.get("method") or ""]:
                if alias:
                    held = calls_of.setdefault(alias.casefold(), (alias, entry.get("method") or call, set()))
                    held[2].add(call.split(".")[-1])
    found, wanted = [], {}
    for item in passages:
        text = str(item.get("text") or "")
        tags = methods.code_tags([text])
        problems = [(path, locator) for path, locator in tags
                    if provenance.code_tag_problem(read, {"path": path, "locator": locator}) is not None]
        for path, locator in problems:
            found.append({"passage": item["id"], "heading": _one_line(item.get("heading")), "named": "{code:%s#%s}" % (path, locator),
                          "why": "`main` holds no such code"})
        if tags:
            continue  # the code it names is what stands behind it, there or not
        named = {}
        for folded, (alias, method, calls) in calls_of.items():
            if methods._names(alias, text):
                named.setdefault(method, (alias, set()))[1].update(calls)
        for method, (alias, calls) in named.items():
            wanted.setdefault(item["id"], []).append((item, alias, method, calls))
    every = {call for entries in wanted.values() for _, _, _, calls in entries for call in calls}
    called = _calls(book.project, every)
    for identifier, entries in wanted.items():
        for item, alias, method, calls in entries:
            if not calls & called:
                found.append({"passage": identifier, "heading": _one_line(item.get("heading")), "named": alias,
                              "why": "no code under `code/` calls %s (%s)" % (method, ", ".join(sorted(calls)))})
    return found


def gap_lines(entries):
    """The outline's Gaps lines for the methods with no code behind them."""
    lines = []
    for entry in entries:
        if entry["named"].startswith("{code:"):
            lines.append('- Methods: "%s" names %s (%s), which `main` does not hold; the code repository does not reproduce it.'
                         % (entry["heading"], entry["named"], entry["passage"]))
        else:
            lines.append('- Methods: "%s" names %s (%s), which no code under `code/` calls; the code repository does not '
                         "reproduce it." % (entry["heading"], entry["named"], entry["passage"]))
    return lines


# --- the record ---------------------------------------------------------------------------------------------------


def _empty():
    return {"parameters": [], "software": [], "citations": [], "not_reproduced": [], "setup": None}


def read_record(project_or_ledger):
    """`research/methods_inventory.json` as the last render of Methods wrote it; empty before any."""
    book = ledger_for(project_or_ledger)
    try:
        record = book.read_json(INVENTORY_JSON)
    except (OSError, ValueError):
        return _empty()
    return dict(_empty(), **record) if isinstance(record, dict) else _empty()


def _record(book, rows, listed, proposed, missing):
    """Write what this render generated, when it changed; the setup's part is kept as it is."""
    record = read_record(book)
    fresh = dict(record, parameters=[{key: row.get(key) for key in ("method", "name", "value", "default", "reason", "path", "line",
                                                                     "code", "ticket", "by")} for row in rows],
                 software=listed, citations=proposed,
                 not_reproduced=[dict(entry, reproduced_by_repository=False) for entry in missing])
    if fresh != record or not book.path(INVENTORY_JSON).is_file():
        book.write_json(INVENTORY_JSON, fresh, schema=SCHEMA)


def availability(project_or_ledger):
    """The data and code availability statement's inputs on the code: each Methods method the code repository does not
    reproduce (`not_reproduced`), as code reads them now."""
    return [dict(entry, reproduced_by_repository=False) for entry in no_code(project_or_ledger)]


# --- the setup at a start midway -------------------------------------------------------------------------------------


LEADS_SCHEMA = "code_leads"
_NUMBER = r"[-+]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][-+]?[0-9]+)?"
STATED_WINDOW = 60  # how far after a parameter's name the inherited Methods may state its value, in characters


def _code_files(project):
    """`[(relative path, full path, language)]` of the inherited code under `code/` the parsers read."""
    from wayline.code_dossier import _is_vendored

    root = Path(project) / methods.CODE
    if not root.is_dir():
        return []
    found = []
    for path in sorted(root.rglob("*")):
        language = {".py": "python", ".m": "matlab"}.get(path.suffix.lower())
        relative = path.relative_to(root)
        if language is None or not path.is_file() or _is_vendored(path, root) or any(part.startswith(".") for part in relative.parts):
            continue
        if relative.parts[0] in (LOCKS_DIR,):
            continue
        found.append((path.relative_to(Path(project)).as_posix(), path, language))
    return found


def _parsed(project, run, tools):
    """`({path: text}, [Item], [notes])`: what the parsers see across the inherited code, read whole."""
    from wayline.tools import ToolsError

    tables = {"aliases": methods.aliases(), "defaults": methods.defaults()}
    functions, roots = methods.project_functions(project)
    texts, items, notes = {}, [], []
    for relative, path, language in _code_files(project):
        try:
            texts[relative] = path.read_text(encoding="utf-8", errors="replace")
        except OSError as failure:
            notes.append("%s could not be read: %s" % (relative, failure))
            continue
        if language == "python":
            found, _ = methods.python_items(relative, texts[relative], None, functions, roots, tables, None)
        else:
            try:
                found = methods.matlab_items(relative, methods.matlab_parse(path, run, tools), None, tables)
            except ToolsError as failure:
                notes.append("%s was not parsed: %s" % (relative, failure))
                continue
        items.extend(item for item in found if item.what != "unparsed")
    return texts, items, notes


def _number(text):
    try:
        return float(str(text).strip().strip("'\""))
    except ValueError:
        return None


def _stated_values(name, passages):
    """`[(value, passage id)]`: each number the inherited Methods states for a parameter, within a few words after its
    name (`window of 256 samples`, `$\\sigma = 0.1$`)."""
    spoken = re.escape(name).replace("_", "[ _]")
    pattern = re.compile(r"(?<![\w\\])%s(?!\w)[^.;\n]{0,%d}?(?<![\w.])(%s)(?!\w|\.[0-9])" % (spoken, STATED_WINDOW, _NUMBER),
                         re.IGNORECASE)
    found = []
    for item in passages:
        for match in pattern.finditer(str(item.get("text") or "")):
            value = _number(match.group(1))
            if value is not None:
                found.append((value, item["id"]))
    return found


def _disagreements(items, texts, passages):
    """`[(text, path, line, words)]`: where the inherited Methods and the code disagree, `words` naming what it is about."""
    found = []
    if not passages:
        return found  # no inherited Methods: nothing stated to disagree with
    stated_text = "\n".join(str(item.get("text") or "") for item in passages)
    for item in items:
        if item.kind != "parameter" or item.value in (None, methods.UNSET):
            continue
        value = _number(item.value)
        # A name shorter than three letters (`a`, `k`) is read in prose as a word as often as a parameter: not compared.
        stated = _stated_values(item.name, passages) if len(item.name) >= 3 else []
        if value is None or not stated or any(said == value for said, _ in stated):
            continue
        said = ", ".join(sorted({"%s (%s)" % (("%g" % number), identifier) for number, identifier in stated}))
        found.append(("The inherited Methods states `%s` as %s; the code gives it %s in `%s` (%s)."
                      % (item.name, said, item.value, item.method, item.where), item.path, item.line,
                      [item.method, item.name, Path(item.path).stem]))
    used = {}
    for item in items:
        if item.kind == "used":
            used.setdefault(item.method or item.name, []).append(item)
    for method, calls in used.items():
        aliases = {alias for item in calls for alias in item.aliases if alias}
        if not any(methods._names(alias, stated_text) for alias in aliases):
            first = calls[0]
            found.append(("The code calls `%s` (%s, %s), which the inherited Methods does not state." % (first.name, method, first.where),
                          first.path, first.line, [method, first.name.split(".")[-1]] + sorted(aliases)))
    code_text = "\n".join(texts.values())
    seen = set()
    for language, entries in methods.aliases().items():
        for call, entry in entries.items():
            method = entry.get("method") or call
            aliases = [alias for alias in list(entry.get("aliases") or []) + [method] if alias]
            named = [alias for alias in aliases if methods._names(alias, stated_text)]
            if not named or method in seen or method in used:
                continue
            calls = {other.split(".")[-1] for entries_ in methods.aliases().values() for other, other_entry in entries_.items()
                     if (other_entry.get("method") or other) == method}
            if any(methods._names(name, code_text) for name in calls):
                continue
            seen.add(method)
            where = [item["id"] for item in passages if any(methods._names(alias, str(item.get("text") or "")) for alias in named)]
            found.append(("The inherited Methods states %s (%s, %s), which the code does not call." % (named[0], method, ", ".join(where)),
                          None, None, named + [method]))
    return found


def _using(results, words):
    """The inherited results whose claims name any of `words` (a function's name read with spaces for its underscores);
    every one when none does."""
    wanted = {str(word).replace("_", " ").strip() for word in words if word and len(str(word).strip()) >= 3}
    named = [heading for heading, text in results if any(methods._names(word, text) for word in wanted)]
    return named or [heading for heading, _ in results]


LEAD_PROMPT = """# The inherited code

This project starts midway: it inherits code that produced results it has not checked yet, and each inherited
result is verified before anything is built on it. You are handed one file of that code whole, with its line
numbers. Name what a verification of the results built on it should look into: a value fixed in one place and
another elsewhere, a default that disagrees with what the file says it does, an unseeded random draw, a step that is
skipped or done twice, an index or window that looks off by one. Nothing about style. For each, give `item`, the
exact text of the file it is about as the file writes it, which is kept only when it is found there, and its line.
A file with nothing to look into gets an empty list.

## `%s`

```
%s
```
"""


def _lead_reading(project, path, text, policy, harness_root):
    """One Sonnet reading of one inherited file: `(leads, accounting)`."""
    prompt = LEAD_PROMPT % (path, methods._numbered(text))
    answer, accounting = methods._reading(project, [(path, text, None)], policy=policy, harness_root=harness_root,
                                          prompt=prompt, schema=LEADS_SCHEMA, folder="inherited-code-reading")
    return [entry for entry in (answer or {}).get("leads") or [] if isinstance(entry, dict)], accounting


def setup(project, *, run=None, tools=None, policy=None, harness_root=None, say=lambda text: None):
    """At setup at a start midway, once: compare the inherited Methods with the code and read the inherited code.

    The parser inventory compares the methods and parameters the inherited Methods states with what the parsers see in
    `code/`, and files each disagreement into the verification of the inherited result that uses it. Each file where
    the parsers see developed code gets one Sonnet reading at medium (the `code-reader` role); each concern it names is
    kept only when grep finds its item in the file, and is attached as a lead to the verifications. Returns what
    `research/methods_inventory.json` keeps of it (`setup`), or None for a project that did not start midway. A reading
    a usage window refuses raises `gates.UsageLimited` before anything of the setup is marked done, so it runs again.
    """
    from wayline import HARNESS_ROOT, gates, verification
    from wayline import project as projects
    from wayline.tools import Tools, run_tool

    book = ledger_for(project)
    project = book.project
    if not verification.midway(book):
        return None
    held = read_record(book)
    if held.get("setup") is not None:
        return held["setup"]
    run = run or run_tool
    tools = tools if tools is not None else Tools()
    harness_root = harness_root or HARNESS_ROOT
    by_id = {item["id"]: item for item in sections.read_passages(book)}
    record = verification.current_record(book)
    results = [(result["heading"], "\n".join(str((by_id.get(claim) or {}).get("text") or "") for claim in result["claims"]))
               for result in record["results"]]
    if not results:
        return None
    stated = [item for item in _methods_passages(book) if sections.is_inherited(item)]
    texts, items, notes = _parsed(project, run, tools)
    for note in notes:
        say("  %s" % note)
    filed = {}
    for text, path, line, words in _disagreements(items, texts, stated):
        for heading in _using(results, words):
            filed.setdefault(heading, ([], []))[0].append({"text": text, "path": path, "line": line})
    developed = {}
    for item in items:
        if item.kind == "developed":
            developed.setdefault(item.path, []).append(item.name)
    policy = policy if policy is not None else projects.policy_for(project, harness_root)
    readings, dropped, kept = [], [], 0
    for path in sorted(developed):
        try:
            leads, accounting = _lead_reading(project, path, texts[path], policy, harness_root)
        except gates.UsageLimited:
            raise
        except (methods.MethodsError, gates.GateError, ValueError, OSError) as failure:
            readings.append({"path": path, "session_id": None, "model": None, "usage": None, "lines": len(texts[path].splitlines()),
                             "failed": _one_line(failure) or "the reading could not be taken"})
            continue
        readings.append({key: accounting.get(key) for key in ("session_id", "model", "usage", "lines")} | {"path": path})
        for lead in leads:
            if not methods._grepped(lead.get("item"), texts[path]):
                dropped.append("%s: %s" % (path, lead.get("item")))
                continue
            kept += 1
            words = developed[path] + [Path(path).stem, lead.get("item")]
            for heading in _using(results, words):
                filed.setdefault(heading, ([], []))[1].append({"text": _one_line(lead.get("text")), "path": path,
                                                               "line": lead.get("line")})
    for heading, (disagreements, leads) in filed.items():
        verification.attach_inventory(book, heading, disagreements, leads)
    done = {"commit": verification.intake_commit(project), "disagreements": sum(len(found[0]) for found in filed.values()),
            "readings": readings, "leads": kept, "dropped": dropped}
    with book.lock():
        fresh = read_record(book)
        fresh["setup"] = done
        book.write_json(INVENTORY_JSON, fresh, schema=SCHEMA)
    return done


def block(project_or_ledger):
    """What the inventory adds to `methods.md` after its passages: `(lines, printed)`, `printed` being each row's key
    with its reason's digest, which the render stamp keeps so an edit of a reason is told from a newer one."""
    book = ledger_for(project_or_ledger)
    read = main_read(book.project)
    rows = parameter_rows(book, read)
    lines, printed = [], {}
    if rows:
        lines += _table(rows)
        printed = {row_key(row): _digest(row.get("reason")) for row in rows}
    listed = software(book.project)
    if listed:
        lines += _software_lines(listed)
    passages = _methods_passages(book)
    proposed = citations(book, listed, passages)
    if proposed:
        lines += _citation_lines(proposed)
    _record(book, rows, listed, proposed, no_code(book, passages, read))
    if not lines:
        return [], {}
    return [sections.INVENTORY, ""] + lines, printed


# --- the owner's edit of a reason ------------------------------------------------------------------------------


_ROW = re.compile(r"^\|\s*`([^`]+)`\s*\|\s*`([^`]+)`\s*\|(.*)\|\s*$")
_ROW_CODE = re.compile(r"^\{code:([^#{}\s]+)(?:#L([0-9]+))?\}$")


def _cells(rest):
    cells, current, escaped = [], [], False
    for char in rest:
        if char == "\\" and not escaped:
            escaped = True
            continue
        if char == "|" and not escaped:
            cells.append("".join(current).strip())
            current = []
        else:
            current.append(("\\" if escaped and char != "|" else "") + char)
        escaped = False
    cells.append("".join(current).strip())
    return cells


def taken_reasons(body, printed):
    """`[(parameter key, reason)]`: each row of the table in `body` whose Reason cell differs from the reason the render
    under its stamp printed (`printed`, its digests). A row the render did not print is not read."""
    found = []
    inside = False
    for line in body.splitlines():
        stripped = line.strip()
        if stripped == sections.INVENTORY:
            inside = True
            continue
        if not inside:
            continue
        if stripped == sections.NOTES:
            break
        row = _ROW.match(stripped)
        if row is None:
            continue
        cells = _cells(row.group(3))
        if len(cells) != 4:
            continue
        method, name = row.group(1).strip(), row.group(2).strip()
        reason, code = cells[2], cells[3]
        tag = _ROW_CODE.match(code)
        path, number = (tag.group(1), tag.group(2)) if tag else (None, None)
        key = row_key({"method": method, "name": name, "path": path, "line": number})
        if key not in printed or not _one_line(reason) or _digest(reason) == printed[key]:
            continue
        found.append((parameter_key(method, name, path), _one_line(reason)))
    return found
